class Stack:
    def __init__(self):
        self.stack = []
        self.queue = []

    def push(self, x):
        self.stack.append(x)

    def pop(self):
        if not self.stack:
            return None
        popped = self.stack.pop()
        self.queue.append(popped)
        return popped

    def push_to_back(self, x):
        self.queue.append(x)
        for elem in self.queue:
            self.stack.append(elem)
        self.queue.clear()

    def pop_from_front(self):
        if not self.stack and not self.queue:
            return None
        if self.queue:
            return self.queue.pop()
        else:
            popped = self.stack.pop()
            self.queue.append(popped)
            return popped

# Example usage:
stack = Stack()
stack.push(1)
stack.push(2)
print(stack.pop())  # prints: 2
stack.push_to_back(3)
print(stack.pop_from_front())  # prints: 3
